pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        address payable caller = payable(address(0x1234));
        vm.deal(caller, amount);
        vm.prank(caller);
        uint256 balanceBefore = address(c).balance;
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("addToBalance()"));
        assertTrue(success && address(c).balance == balanceBefore + amount);
    }
}
